import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, a score between 0 and 1
        self.reputation = {}
        # Track cooperation rates of each agent (weighted recent)
        self.coop_rate = {}
        # Track defection rates of each agent
        self.defect_rate = {}
        # Track number of observations per agent
        self.obs_count = {}
        # Track how many times this agent cooperated/defected
        self.my_coop = 0
        self.my_defect = 0
        # Track last opponent ID to use in decide
        self._ctx_opponent_id = None
        # Track recent outcomes with each opponent: (coop, defect) counts
        self.opponent_history = {}
        # Track my own actions history
        self.my_history = []
        # Track global cooperation level
        self.global_coop = 0
        self.global_count = 0
        # Learning rate for reputation updates
        self.alpha = 0.3
        # Initial reputation for unknown agents
        self.default_rep = 0.5
        # Memory window for recent behavior
        self.recent_window = 10

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True  # default
        opp = self._ctx_opponent_id
        # Get opponent reputation, default 0.5
        rep = self.reputation.get(opp, self.default_rep)
        # Get opponent's recent cooperation rate, default 0.5
        opp_coop = self.coop_rate.get(opp, 0.5)
        # Get my history with this opponent
        hist = self.opponent_history.get(opp, (0, 0))
        my_c, my_d = hist
        total = my_c + my_d
        # If I've had interactions, adjust based on reciprocity
        if total > 0:
            my_coop_rate = my_c / total
            # If opponent cooperates often, we cooperate more
            if opp_coop > 0.7:
                return True
            elif opp_coop < 0.3:
                return False
            else:
                # Tit-for-tat with some forgiveness
                if my_coop_rate > 0.7:
                    return True
                elif my_coop_rate < 0.3:
                    return False
                else:
                    # Mixed strategy: use reputation
                    return rep > 0.5
        else:
            # First encounter: cooperate if reputation decent
            return rep > 0.4

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global stats
        self.global_count += 1
        if donor_action == 'cooperate':
            self.global_coop += 1
        if recipient_action == 'cooperate':
            self.global_coop += 1

        # Update self observations
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_coop += 1
            else:
                self.my_defect += 1
            self.my_history.append(donor_action)
            if len(self.my_history) > 100:
                self.my_history.pop(0)
            # Update opponent history based on recipient action
            if recipient_id != self.agent_id:
                hist = self.opponent_history.get(recipient_id, (0, 0))
                if recipient_action == 'cooperate':
                    hist = (hist[0] + 1, hist[1])
                else:
                    hist = (hist[0], hist[1] + 1)
                self.opponent_history[recipient_id] = hist
        elif recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_coop += 1
            else:
                self.my_defect += 1
            self.my_history.append(recipient_action)
            if len(self.my_history) > 100:
                self.my_history.pop(0)
            if donor_id != self.agent_id:
                hist = self.opponent_history.get(donor_id, (0, 0))
                if donor_action == 'cooperate':
                    hist = (hist[0] + 1, hist[1])
                else:
                    hist = (hist[0], hist[1] + 1)
                self.opponent_history[donor_id] = hist

        # Update reputation for both parties (excluding self)
        if donor_id != self.agent_id:
            self._update_agent_stats(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_agent_stats(recipient_id, recipient_action)

    def _update_agent_stats(self, agent_id: int, action: str) -> None:
        # Update coop/defect rates with exponential moving average
        if action == 'cooperate':
            current = self.coop_rate.get(agent_id, 0.5)
            new = current * (1 - self.alpha) + 1.0 * self.alpha
            self.coop_rate[agent_id] = new
            # Defect rate decreases
            current_def = self.defect_rate.get(agent_id, 0.5)
            new_def = current_def * (1 - self.alpha) + 0.0 * self.alpha
            self.defect_rate[agent_id] = new_def
        else:
            current = self.coop_rate.get(agent_id, 0.5)
            new = current * (1 - self.alpha) + 0.0 * self.alpha
            self.coop_rate[agent_id] = new
            current_def = self.defect_rate.get(agent_id, 0.5)
            new_def = current_def * (1 - self.alpha) + 1.0 * self.alpha
            self.defect_rate[agent_id] = new_def

        # Update reputation: cooperation good, defection bad
        current_rep = self.reputation.get(agent_id, self.default_rep)
        if action == 'cooperate':
            # Reward cooperation
            new_rep = current_rep * (1 - self.alpha) + 1.0 * self.alpha
        else:
            # Punish defection
            new_rep = current_rep * (1 - self.alpha) + 0.0 * self.alpha
        self.reputation[agent_id] = new_rep

        # Update observation count
        self.obs_count[agent_id] = self.obs_count.get(agent_id, 0) + 1

