class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation: for each agent, count of cooperative acts minus defections witnessed
        self.reputation = {}
        # Track cooperation rate with each opponent (for reciprocity)
        self.partner_coop = {}  # agent_id -> [coop_count, total_interactions]
        # Track own actions history: list of (opponent_id, own_action)
        self.my_history = []
        # Track recent defections by others to punish
        self.recent_defections = {}
        # Generous tit-for-tat parameter: probability to cooperate after opponent defected
        self.generosity = 0.1
        # Memory window for reputation (recent 10 observations)
        self.recent_reputation = {}
        # For each agent, list of last 10 observed actions (1 for cooperate, 0 for defect)
        self.action_memory = {}
        # Own cooperation count
        self.my_coop_count = 0
        self.my_defect_count = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Default: cooperate if no info
        if opponent not in self.reputation:
            # If we have interacted before, use reciprocity
            if opponent in self.partner_coop:
                coop_rate = self.partner_coop[opponent][0] / max(1, self.partner_coop[opponent][1])
                return coop_rate >= 0.5
            return True

        # Reputation-based: cooperate if opponent's reputation is positive
        rep = self.reputation.get(opponent, 0)
        # Also consider recent behavior
        recent = self.recent_reputation.get(opponent, 0)
        combined = 0.7 * rep + 0.3 * recent

        # If opponent has been defecting a lot recently, defect
        if combined < -0.2:
            return False
        # If we have a history with them, use tit-for-tat with forgiveness
        if opponent in self.partner_coop:
            coop_count, total = self.partner_coop[opponent]
            if total > 0:
                opp_coop_rate = coop_count / total
                # If opponent cooperated last time, cooperate; else maybe forgive
                if self.my_history and self.my_history[-1][0] == opponent:
                    last_opp_action = self.my_history[-1][1]  # this is my action, not opponent's
                    # Need to track opponent's last action separately
                # Get opponent's last action from memory
                if opponent in self.action_memory:
                    last_acts = self.action_memory[opponent]
                    if last_acts:
                        last_opp = last_acts[-1]
                        if last_opp == 1:
                            return True
                        else:
                            # Forgive with probability generosity
                            return random.random() > self.generosity
                # No memory, use cooperation rate
                return opp_coop_rate >= 0.5
        # No interaction history, use reputation
        return combined >= 0

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Convert actions to numeric
        d_coop = 1 if donor_action == 'cooperate' else 0
        r_coop = 1 if recipient_action == 'cooperate' else 0

        # Update reputation and recent reputation for both agents
        for agent_id, action in [(donor_id, d_coop), (recipient_id, r_coop)]:
            if action == 1:
                self.reputation[agent_id] = self.reputation.get(agent_id, 0) + 1
            else:
                self.reputation[agent_id] = self.reputation.get(agent_id, 0) - 1
            # Update recent reputation (moving average with limited window)
            if agent_id not in self.recent_reputation:
                self.recent_reputation[agent_id] = 0.0
            # Use exponential moving average with decay
            self.recent_reputation[agent_id] = 0.9 * self.recent_reputation[agent_id] + 0.1 * (1 if action == 1 else -1)

        # Update action memory for both agents
        for agent_id, action in [(donor_id, d_coop), (recipient_id, r_coop)]:
            if agent_id not in self.action_memory:
                self.action_memory[agent_id] = []
            self.action_memory[agent_id].append(action)
            if len(self.action_memory[agent_id]) > 10:
                self.action_memory[agent_id].pop(0)

        # If we are one of the players, update partner cooperation stats and own history
        if donor_id == self.agent_id:
            self._update_own_interaction(recipient_id, d_coop, r_coop)
        elif recipient_id == self.agent_id:
            self._update_own_interaction(donor_id, r_coop, d_coop)
        else:
            # Third-party: maybe track defections for punishment
            if donor_action == 'defect':
                self.recent_defections[donor_id] = self.recent_defections.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.recent_defections[recipient_id] = self.recent_defections.get(recipient_id, 0) + 1

        # Update own counts
        if donor_id == self.agent_id:
            if d_coop == 1:
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1
        elif recipient_id == self.agent_id:
            if r_coop == 1:
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1

    def _update_own_interaction(self, opponent_id, my_action, opp_action):
        # Update partner cooperation stats
        if opponent_id not in self.partner_coop:
            self.partner_coop[opponent_id] = [0, 0]
        self.partner_coop[opponent_id][1] += 1
        if opp_action == 1:
            self.partner_coop[opponent_id][0] += 1
        # Record own history (opponent_id, my_action)
        self.my_history.append((opponent_id, my_action))
        if len(self.my_history) > 20:
            self.my_history.pop(0)

