import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.observed_coop = 0
        self.observed_defect = 0
        self.history = {}
        self._ctx_opponent_id = None
        self.round_count = 0
        self.my_recent_actions = []
        self.trust = {}
        # New: Track cooperation rate of each opponent to be more nuanced
        self.opponent_coop_rate = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        total_obs = self.observed_coop + self.observed_defect
        if total_obs > 0:
            coop_ratio = self.observed_coop / total_obs
        else:
            coop_ratio = 0.5

        hist = self.history.get(opponent, [])
        if hist:
            my_last, their_last = hist[-1]
            if their_last == 'cooperate':
                base_coop = 0.7
            else:
                base_coop = 0.3
        else:
            base_coop = 0.5 + 0.3 * (coop_ratio - 0.5)

        trust_val = self.trust.get(opponent, 0.5)
        base_coop = 0.5 * base_coop + 0.5 * trust_val

        # New: Use opponent-specific cooperation rate to adjust decision
        opp_rate = self.opponent_coop_rate.get(opponent, 0.5)
        base_coop = base_coop * 0.8 + 0.2 * opp_rate

        phase = self.round_count % 30
        if phase < 5:
            base_coop += 0.1
        elif phase > 20:
            base_coop -= 0.1

        prob = max(0.0, min(1.0, base_coop))
        self.round_count += 1
        return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_action == 'cooperate':
            self.observed_coop += 1
        else:
            self.observed_defect += 1
        if recipient_action == 'cooperate':
            self.observed_coop += 1
        else:
            self.observed_defect += 1

        if donor_id == self.agent_id:
            opponent = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opponent = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            # Update opponent cooperation rates for third parties
            if donor_id not in self.opponent_coop_rate:
                self.opponent_coop_rate[donor_id] = 0.5
            if recipient_id not in self.opponent_coop_rate:
                self.opponent_coop_rate[recipient_id] = 0.5
            self.opponent_coop_rate[donor_id] = self.opponent_coop_rate[donor_id] * 0.9 + (0.1 if donor_action == 'cooperate' else 0.0)
            self.opponent_coop_rate[recipient_id] = self.opponent_coop_rate[recipient_id] * 0.9 + (0.1 if recipient_action == 'cooperate' else 0.0)

            if donor_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) + 0.05
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) - 0.05
            if recipient_action == 'cooperate':
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) + 0.05
            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.05
            return

        if opponent not in self.history:
            self.history[opponent] = []
        self.history[opponent].append((my_action, their_action))
        if len(self.history[opponent]) > 30:
            self.history[opponent] = self.history[opponent][-30:]

        if their_action == 'cooperate':
            self.trust[opponent] = self.trust.get(opponent, 0.5) + 0.1
        else:
            self.trust[opponent] = self.trust.get(opponent, 0.5) - 0.1
        self.trust[opponent] = max(0.0, min(1.0, self.trust[opponent]))

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 30:
            self.my_recent_actions = self.my_recent_actions[-30:]

        # Update opponent-specific cooperation rate for direct interactions
        if opponent not in self.opponent_coop_rate:
            self.opponent_coop_rate[opponent] = 0.5
        self.opponent_coop_rate[opponent] = self.opponent_coop_rate[opponent] * 0.9 + (0.1 if their_action == 'cooperate' else 0.0)

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.coop_rate = {}
        self.my_actions = []
        self.round = 0
        self.trust_threshold = 0.5
        self.memory_limit = 30
        # Track recent defections by each opponent to detect patterns
        self.recent_defections = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5
        key = (self.agent_id, opponent)
        if key in self.history and len(self.history[key]) > 0:
            coop = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            opp_coop_rate = coop / total
            # Penalize if opponent has a streak of recent defections
            recent_defect_count = self.recent_defections.get(opponent, 0)
            if recent_defect_count >= 3:
                return False
            if opp_coop_rate >= 0.5 or self.reputation[opponent] >= self.trust_threshold:
                return True
            else:
                if len(self.history[key]) > 5 and random.random() < 0.08:
                    return True
                return False
        else:
            return self.reputation[opponent] >= self.trust_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.my_actions.append(my_action)
            if len(self.my_actions) > self.memory_limit:
                self.my_actions.pop(0)
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            key = (self.agent_id, opponent)
            if key not in self.history:
                self.history[key] = []
            self.history[key].append((my_action, opp_action, self.round))
            if len(self.history[key]) > self.memory_limit:
                self.history[key].pop(0)
            coop_count = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            self.coop_rate[opponent] = coop_count / total if total > 0 else 0.5
            delta = 0.1 if opp_action == 'cooperate' else -0.1
            self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + delta))
            # Update recent defection streak for opponent
            if opp_action == 'defect':
                self.recent_defections[opponent] = self.recent_defections.get(opponent, 0) + 1
            else:
                self.recent_defections[opponent] = 0
        else:
            if donor_action == 'cooperate':
                delta_d = 0.05
            else:
                delta_d = -0.05
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation.get(donor_id, 0.5) + delta_d))
            if recipient_action == 'cooperate':
                delta_r = 0.03
            else:
                delta_r = -0.03
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation.get(recipient_id, 0.5) + delta_r))

