        self.own_recent = []
        self.gen = 0
        self.default_rep = 0.0
        self.trust_threshold = 0.2
        self.decay_rate = 0.95
        # New: track the last observed action for each agent (most recent)
        self.last_observed_action = {}
        # New: track how many times we've been observed by others (self-monitoring)
        self.self_observed_count = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, self.default_rep)

        hist = self.coop_history.get(opponent, [])
        if hist:
            last = hist[-1]
            if last == 'cooperate':
                rep += 0.3
            else:
                rep -= 0.3

        # Additional: if we've never seen this opponent, be more cautious
        if opponent not in self.observed_counts:
            rep -= 0.1

        if rep > self.trust_threshold:
            decision = True
        elif rep < -self.trust_threshold:
            decision = False
        else:
            prob = (rep + 1) / 2
            decision = random.random() < prob

        self.own_recent.append(decision)
        if len(self.own_recent) > 50:
            self.own_recent.pop(0)

        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_delta = 0.5 if donor_action == 'cooperate' else -0.5
        recipient_delta = 0.5 if recipient_action == 'cooperate' else -0.5

        self._update_reputation(donor_id, donor_delta)
        self._update_reputation(recipient_id, recipient_delta)

        self._increment_count(donor_id)
        self._increment_count(recipient_id)

        # New: track the most recent action for each agent
        self.last_observed_action[donor_id] = donor_action
        self.last_observed_action[recipient_id] = recipient_action

        # If we are involved, record direct reciprocity info
        if donor_id == self.agent_id:
            self._record_recipient_action(recipient_id, recipient_action)
            # New: if we are donor, also record our own action for self-monitoring
            self.self_observed_count += 1
        if recipient_id == self.agent_id:
            self._record_recipient_action(donor_id, donor_action)
            # New: if we are recipient, also record our own action (we are recipient, but our action is not passed; we can infer from the context? Actually we don't have our action here, but we can note that we were observed)
            self.self_observed_count += 1

        # Decay old reputations slightly
        self._decay_reputations()

    def _update_reputation(self, agent_id, delta):
        current = self.reputation.get(agent_id, self.default_rep)
        new_val = max(-1.0, min(1.0, current + delta))
        self.reputation[agent_id] = new_val

    def _increment_count(self, agent_id):
        self.observed_counts[agent_id] = self.observed_counts.get(agent_id, 0) + 1

    def _record_recipient_action(self, agent_id, action):
        if agent_id not in self.coop_history:
