        self.my_recent_actions = []
        self.trust = {}
        self.self_coop_count = 0
        self.self_defect_count = 0
        self.recent_defections = {}
        # NEW: Track cooperation ratio per opponent for more nuanced decisions
        self.opponent_coop_ratio = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        self.round_count += 1

        total_obs = self.observed_coop + self.observed_defect
        if total_obs > 0:
            coop_ratio = self.observed_coop / total_obs
        else:
            coop_ratio = 0.5

        hist = self.history.get(opponent, [])
        if hist:
            my_last, their_last = hist[-1]
            if their_last == 'cooperate':
                base_coop = 0.7
            else:
                base_coop = 0.3
        else:
            base_coop = 0.5 + 0.3 * (coop_ratio - 0.5)

        trust_val = self.trust.get(opponent, 0.5)
        base_coop = 0.5 * base_coop + 0.5 * trust_val

        phase = self.round_count % 30
        if phase < 5:
            base_coop += 0.1
        elif phase > 20:
            base_coop -= 0.1

        self_total = self.self_coop_count + self.self_defect_count
        if self_total > 0:
            self_coop_ratio = self.self_coop_count / self_total
            if self_coop_ratio < 0.4:
                base_coop += 0.15
            elif self_coop_ratio > 0.7:
                base_coop -= 0.05

        def_count = self.recent_defections.get(opponent, 0)
        if def_count >= 3:
            base_coop -= 0.2
        elif def_count == 2:
            base_coop -= 0.1

        # NEW: Use opponent-specific cooperation ratio to adjust behavior
        opp_ratio = self.opponent_coop_ratio.get(opponent, 0.5)
        if opp_ratio < 0.3:
            base_coop -= 0.1
        elif opp_ratio > 0.7:
            base_coop += 0.1

        prob = max(0.0, min(1.0, base_coop))
        return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_action == 'cooperate':
