        # Simple exponential moving average
        if their_action == 'cooperate':
            self.opponent_coop_ratio[opponent] = 0.9 * self.opponent_coop_ratio[opponent] + 0.1 * 1.0
        else:
            self.opponent_coop_ratio[opponent] = 0.9 * self.opponent_coop_ratio[opponent] + 0.1 * 0.0

