class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.obs_count = {}
        self.own_coop_count = 0
        self.own_defect_count = 0
        self.recent_outcomes = []
        self.last_action_against_me = {}
        self.round_counter = 0
        self.last_actions = {}
        self.personal_rep_weight = 0.7
        self.obs_rep_weight = 0.3
        # New: Track reputation volatility to adjust trust
        self.rep_var = {}
        self.rep_history = {}
        # New: Track frequency of interactions with each agent
        self.interaction_counts = {}
        # New: Track average cooperation of each agent (smoothed)
        self.avg_coop = {}

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            return 0.0
        total = self.reputation[agent_id]
        count = self.obs_count[agent_id]
        return total / count if count > 0 else 0.0

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
            self.obs_count[agent_id] = 0
            self.rep_var[agent_id] = 0.0
            self.rep_history[agent_id] = []
            self.avg_coop[agent_id] = 0.5  # initial neutral
        self.reputation[agent_id] += delta
        self.obs_count[agent_id] += 1
        # Update volatility based on deviation from current average
        current_avg = self.reputation[agent_id] / self.obs_count[agent_id]
        self.rep_history[agent_id].append(delta)
        if len(self.rep_history[agent_id]) > 10:
            self.rep_history[agent_id].pop(0)
        if len(self.rep_history[agent_id]) >= 2:
            deviations = [abs(x - current_avg) for x in self.rep_history[agent_id]]
            self.rep_var[agent_id] = sum(deviations) / len(deviations)
        # Update average cooperation rate (smoothed)
        if delta > 0:
            self.avg_coop[agent_id] = 0.9 * self.avg_coop[agent_id] + 0.1 * 1.0
        else:
            self.avg_coop[agent_id] = 0.9 * self.avg_coop[agent_id] + 0.1 * 0.0

    def decide(self) -> bool:
        opp_id = self._ctx_opponent_id
        opp_rep = self._get_reputation(opp_id)

        # Compute own cooperation rate
        total_own = self.own_coop_count + self.own_defect_count
        coop_rate = self.own_coop_count / total_own if total_own > 0 else 0.5

        # Adaptive threshold based on cooperation rate and personal interactions
        threshold = 0.5 * coop_rate - 0.25

        # Add deterministic noise
        rnd = (self.round_counter * 7 + self.agent_id * 13) % 100 / 100.0
        threshold += (rnd - 0.5) * 0.1

        # Personal interaction override: if we have direct experience, weight it more
        if opp_id in self.last_action_against_me:
            personal_action = self.last_action_against_me[opp_id]
            if personal_action == 'defect':
                threshold += 0.3
            else:
                threshold -= 0.1

        # Recent observed defections increase caution
        if opp_id in self.last_actions:
            recent_actions = self.last_actions[opp_id]
            if len(recent_actions) >= 3:
                defect_count = recent_actions.count('defect')
                if defect_count >= 2:
                    threshold += 0.4
                elif defect_count == 1:
                    threshold += 0.2

        # Extreme reputation shortcuts
        if opp_rep > 1.5:
            return True
        if opp_rep < -1.5:
            return False

        # Combine reputation with personal interaction bias
        if opp_id in self.last_action_against_me:
            personal_score = 1.0 if self.last_action_against_me[opp_id] == 'cooperate' else -1.0
            blended_rep = self.obs_rep_weight * opp_rep + self.personal_rep_weight * personal_score
        else:
            blended_rep = opp_rep

        # New: Adjust based on reputation volatility - if opponent is unpredictable, be more cautious
        if opp_id in self.rep_var and self.obs_count[opp_id] > 2:
            volatility = self.rep_var[opp_id]
            if volatility > 0.8:
                threshold += 0.15  # extra caution for volatile opponents
            elif volatility < 0.2:
                threshold -= 0.05  # slight trust for stable opponents

        # New: Adjust based on interaction frequency - if we've interacted infrequently, be more cautious
        if opp_id in self.interaction_counts and self.interaction_counts[opp_id] < 2:
            threshold += 0.1  # less trust for unfamiliar opponents

        # New: Adjust based on smoothed average cooperation - if historically cooperative, trust more
        if opp_id in self.avg_coop and self.obs_count[opp_id] > 5:
            if self.avg_coop[opp_id] > 0.7:
                threshold -= 0.1
            elif self.avg_coop[opp_id] < 0.3:
                threshold += 0.1

        return blended_rep >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update donor reputation
        delta_donor = 1.0 if donor_action == 'cooperate' else -1.0
        self._update_reputation(donor_id, delta_donor)

        # Update recipient reputation
        delta_recipient = 1.0 if recipient_action == 'cooperate' else -1.0
        self._update_reputation(recipient_id, delta_recipient)

        # Track recent actions (last 5)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.last_actions:
                self.last_actions[agent_id] = []
            self.last_actions[agent_id].append(action)
            if len(self.last_actions[agent_id]) > 5:
                self.last_actions[agent_id].pop(0)

        # Update interaction counts for both agents
        for agent_id in [donor_id, recipient_id]:
            if agent_id not in self.interaction_counts:
                self.interaction_counts[agent_id] = 0
            self.interaction_counts[agent_id] += 1

        # Self-judgment handling
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop_count += 1
            else:
                self.own_defect_count += 1
            opp_id = recipient_id
            self.last_action_against_me[opp_id] = recipient_action
        elif recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_coop_count += 1
            else:
                self.own_defect_count += 1
            opp_id = donor_id
            self.last_action_against_me[opp_id] = donor_action

        self.round_counter += 1

