        total_obs = self.observed_coop + self.observed_defect
        if total_obs > 0:
            coop_ratio = self.observed_coop / total_obs
        else:
            coop_ratio = 0.5

        # Personal history with opponent
        hist = self.history.get(opponent, [])
        if hist:
            my_last, their_last = hist[-1]
            if their_last == 'cooperate':
                base_coop = 0.7
            else:
                base_coop = 0.3
        else:
            base_coop = 0.5 + 0.3 * (coop_ratio - 0.5)

        # Adjust with trust
        trust_val = self.trust.get(opponent, 0.5)
        base_coop = 0.5 * base_coop + 0.5 * trust_val

        # Phase adjustment
        phase = self.round_count % 30
        if phase < 5:
            base_coop += 0.1
        elif phase > 20:
            base_coop -= 0.1

        # NEW: Partner-specific generosity - if this partner has cooperated often
        # in past interactions, be more cooperative with them
        partner_coops = self.partner_coop_counts.get(opponent, 0)
        if partner_coops > 3:
