class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation_counts = {}
        self.self_histories = []
        self.trust_scores = {}
        self.observation_counts = {}
        self._ctx_opponent_id = None
        self.exploration_rate = 0.05
        # Track recent behavior of each agent in a sliding window (last 10 observations)
        self.recent_actions = {}  # agent_id -> deque of recent actions ('cooperate'/'defect')
        # New: track payoff history against each opponent to adjust trust updates
        self.payoff_history = {}  # agent_id -> list of (my_action, opp_action)

    def decide(self) -> bool:
        opp_id = self._ctx_opponent_id if self._ctx_opponent_id is not None else self.agent_id
        if opp_id not in self.trust_scores:
            return True
        trust = self.trust_scores[opp_id]
        if random.random() < self.exploration_rate:
            return True if random.random() < 0.5 else False
        # Use a dynamic threshold: if we have recent data, be more cautious about defectors
        # Lower threshold if opponent has cooperated recently, higher if defected recently
        if opp_id in self.recent_actions:
            recent = self.recent_actions[opp_id]
            if recent and recent[-1] == 'cooperate':
                threshold = 0.4  # more forgiving
            elif recent and recent[-1] == 'defect':
                threshold = 0.6  # less forgiving
            else:
                threshold = 0.5
        else:
            threshold = 0.5
        return trust >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update recent actions for both agents (if not self)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if agent_id not in self.recent_actions:
                self.recent_actions[agent_id] = []
            self.recent_actions[agent_id].append(action)
            # Keep only last 10
            if len(self.recent_actions[agent_id]) > 10:
                self.recent_actions[agent_id] = self.recent_actions[agent_id][-10:]

        # Update reputation and trust as before
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                opp_id = recipient_id if donor_id == self.agent_id else donor_id
                own_action = donor_action if donor_id == self.agent_id else recipient_action
                opp_action = recipient_action if donor_id == self.agent_id else donor_action
                self.self_histories.append((opp_id, own_action, opp_action))
                # Record payoff history
                if opp_id not in self.payoff_history:
                    self.payoff_history[opp_id] = []
                self.payoff_history[opp_id].append((own_action, opp_action))
                if opp_id not in self.trust_scores:
                    self.trust_scores[opp_id] = 0.5
                # Adaptive update: if opponent has been more cooperative in recent interactions, increase trust more
                recent_payoffs = self.payoff_history[opp_id][-5:]  # last 5 interactions
                coop_rate = sum(1 for a, b in recent_payoffs if b == 'cooperate') / len(recent_payoffs) if recent_payoffs else 0.5
                if opp_action == 'cooperate':
                    # If opponent has high recent cooperation, reward more; else reward less
                    bonus = 0.1 + 0.1 * coop_rate
                    self.trust_scores[opp_id] = min(1.0, self.trust_scores[opp_id] + bonus)
                else:
                    # If opponent defected but recent cooperation is low, punish more
                    penalty = 0.1 + 0.1 * (1 - coop_rate)
                    self.trust_scores[opp_id] = max(0.0, self.trust_scores[opp_id] - penalty)
            else:
                if agent_id not in self.reputation_counts:
