            return True
        coop_rate = sum(self.history[opponent]) / len(self.history[opponent])
        if opponent in self.observed_defections:
            penalty = self.observed_defections[opponent] * 0.1
            coop_rate -= penalty
        # Strong retaliation: if they defected against me recently, defect
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            return False
        if coop_rate < 0.5 and random.random() < self.generosity:
            return True
        return coop_rate >= 0.5

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.round_count += 1
        donor_delta = 1.0 if donor_action == 'cooperate' else -1.0
        recipient_delta = 1.0 if recipient_action == 'cooperate' else -1.0
        self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + donor_delta
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + recipient_delta
        for agent in (donor_id, recipient_id):
            self.reputation[agent] = max(-20.0, min(20.0, self.reputation[agent]))

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                self.observed_defections[donor_id] = self.observed_defections.get(donor_id, 0) + 1
            else:
                self.observed_cooperations[donor_id] = self.observed_cooperations.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.observed_defections[recipient_id] = self.observed_defections.get(recipient_id, 0) + 1
            else:
                self.observed_cooperations[recipient_id] = self.observed_cooperations.get(recipient_id, 0) + 1

        if donor_id == self.agent_id:
            self.my_coop_count += 1 if donor_action == 'cooperate' else 0
            self.my_defect_count += 1 if donor_action == 'defect' else 0
            if recipient_id not in self.history:
                self.history[recipient_id] = []
                self.recent_encounters[recipient_id] = []
            self.history[recipient_id].append(1 if donor_action == 'cooperate' else 0)
            self.recent_encounters[recipient_id].append(1 if donor_action == 'cooperate' else 0)
            if len(self.recent_encounters[recipient_id]) > 10:
                self.recent_encounters[recipient_id].pop(0)
        elif recipient_id == self.agent_id:
            self.my_coop_count += 1 if recipient_action == 'cooperate' else 0
            self.my_defect_count += 1 if recipient_action == 'defect' else 0
            if donor_id not in self.history:
                self.history[donor_id] = []
                self.recent_encounters[donor_id] = []
            self.history[donor_id].append(1 if recipient_action == 'cooperate' else 0)
            self.recent_encounters[donor_id].append(1 if recipient_action == 'cooperate' else 0)
            if len(self.recent_encounters[donor_id]) > 10:
                self.recent_encounters[donor_id].pop(0)
            # Track defections against me with a decay factor
            if donor_action == 'defect':
                self.defection_memory[donor_id] = self.defection_memory.get(donor_id, 0) + 1
            else:
                self.defection_memory[donor_id] = max(0, self.defection_memory.get(donor_id, 0) - 1)
        else:
            pass

    def _get_coop_rate(self, opponent):
        if opponent not in self.recent_encounters or len(self.recent_encounters[opponent]) == 0:
            return 0.5
        recent = self.recent_encounters[opponent]
        weights = [i+1 for i in range(len(recent))]
        total_weight = sum(weights)
        weighted_sum = sum(w * action for w, action in zip(weights, recent))
        return weighted_sum / total_weight

