class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.interactions = {}
        self.recent_encounters = {}
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.round_count = 0
        self.observed_defections = {}
        self.observed_cooperations = {}
        self.observed_total = {}
        self.opponent_streaks = {}
        # Additional memory for forgiveness/revenge dynamics
        self.opponent_last_action = {}  # Track the last action each opponent took against us
        self.forgiveness = {}  # Track how forgiving we are toward each opponent

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If we have no direct history, use third-party observations
        if opponent not in self.history or len(self.history[opponent]) == 0:
            # If opponent has a reputation for defecting, defect
            if opponent in self.observed_defections and self.observed_defections[opponent] > 2:
                return False
            # If opponent has a good reputation, cooperate
            if opponent in self.observed_cooperations and self.observed_total.get(opponent, 0) > 0:
                coop_ratio = self.observed_cooperations[opponent] / self.observed_total[opponent]
                if coop_ratio > 0.7:
                    return True
            return True  # Default to cooperate

        coop_rate = sum(self.history[opponent]) / len(self.history[opponent])
        # Apply reputation penalty based on observed defections
        if opponent in self.observed_total and self.observed_total[opponent] > 0:
            defect_ratio = self.observed_defections.get(opponent, 0) / self.observed_total[opponent]
            penalty = defect_ratio * 0.7  # More aggressive penalty
            coop_rate -= penalty

        # Apply streak penalty: recent defection streaks are punished more
        if opponent in self.opponent_streaks:
            streak = self.opponent_streaks[opponent]
            if streak < 0:
                coop_rate -= abs(streak) * 0.15  # Stronger streak penalty

        # Forgiveness mechanism: if opponent cooperated last time we interacted, boost cooperation
        if opponent in self.opponent_last_action and self.opponent_last_action[opponent] == 'cooperate':
            coop_rate += 0.2  # Reward for last cooperation
        # Revenge mechanism: if opponent defected last time, punish more
        elif opponent in self.opponent_last_action and self.opponent_last_action[opponent] == 'defect':
            coop_rate -= 0.3  # Strong punishment

        # Adaptive threshold based on overall trust in opponent
        if opponent in self.forgiveness:
            coop_rate += self.forgiveness[opponent] * 0.1

        return coop_rate >= 0.5

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.round_count += 1
        donor_delta = 1.0 if donor_action == 'cooperate' else -1.0
        recipient_delta = 1.0 if recipient_action == 'cooperate' else -1.0
        self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + donor_delta
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + recipient_delta
        for agent in (donor_id, recipient_id):
            self.reputation[agent] = max(-20.0, min(20.0, self.reputation[agent]))

        # Update third-party observation counts
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self.observed_total[donor_id] = self.observed_total.get(donor_id, 0) + 1
            self.observed_total[recipient_id] = self.observed_total.get(recipient_id, 0) + 1
            if donor_action == 'defect':
                self.observed_defections[donor_id] = self.observed_defections.get(donor_id, 0) + 1
            else:
                self.observed_cooperations[donor_id] = self.observed_cooperations.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.observed_defections[recipient_id] = self.observed_defections.get(recipient_id, 0) + 1
            else:
                self.observed_cooperations[recipient_id] = self.observed_cooperations.get(recipient_id, 0) + 1

        # Update streak tracking for each observed agent
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent != self.agent_id:
                if agent not in self.opponent_streaks:
                    self.opponent_streaks[agent] = 0
                if action == 'cooperate':
                    self.opponent_streaks[agent] = max(1, self.opponent_streaks[agent] + 1)
                else:
                    self.opponent_streaks[agent] = min(-1, self.opponent_streaks[agent] - 1)

        # Update direct interaction history and last action
        if donor_id == self.agent_id:
            self.my_coop_count += 1 if donor_action == 'cooperate' else 0
            self.my_defect_count += 1 if donor_action == 'defect' else 0
            if recipient_id not in self.history:
                self.history[recipient_id] = []
                self.recent_encounters[recipient_id] = []
            self.history[recipient_id].append(1 if donor_action == 'cooperate' else 0)
            self.recent_encounters[recipient_id].append(1 if donor_action == 'cooperate' else 0)
            if len(self.recent_encounters[recipient_id]) > 10:
                self.recent_encounters[recipient_id].pop(0)
            # Store opponent's last action (what recipient did to us)
            self.opponent_last_action[recipient_id] = recipient_action
            # Update forgiveness: if opponent cooperates, we become more forgiving; if defects, less
            if recipient_action == 'cooperate':
                self.forgiveness[recipient_id] = self.forgiveness.get(recipient_id, 0.5) + 0.1
            else:
                self.forgiveness[recipient_id] = self.forgiveness.get(recipient_id, 0.5) - 0.1
            self.forgiveness[recipient_id] = max(0.0, min(1.0, self.forgiveness[recipient_id]))
        elif recipient_id == self.agent_id:
            self.my_coop_count += 1 if recipient_action == 'cooperate' else 0
            self.my_defect_count += 1 if recipient_action == 'defect' else 0
            if donor_id not in self.history:
                self.history[donor_id] = []
                self.recent_encounters[donor_id] = []
            self.history[donor_id].append(1 if recipient_action == 'cooperate' else 0)
            self.recent_encounters[donor_id].append(1 if recipient_action == 'cooperate' else 0)
            if len(self.recent_encounters[donor_id]) > 10:
                self.recent_encounters[donor_id].pop(0)
            # Store opponent's last action (what donor did to us)
            self.opponent_last_action[donor_id] = donor_action
            # Update forgiveness
            if donor_action == 'cooperate':
                self.forgiveness[donor_id] = self.forgiveness.get(donor_id, 0.5) + 0.1
            else:
                self.forgiveness[donor_id] = self.forgiveness.get(donor_id, 0.5) - 0.1
            self.forgiveness[donor_id] = max(0.0, min(1.0, self.forgiveness[donor_id]))
        else:
            pass

    def _get_coop_rate(self, opponent):
        if opponent not in self.recent_encounters or len(self.recent_encounters[opponent]) == 0:
            return 0.5
        recent = self.recent_encounters[opponent]
        weights = [i+1 for i in range(len(recent))]
        total_weight = sum(weights)
        weighted_sum = sum(w * action for w, action in zip(weights, recent))
        return weighted_sum / total_weight

