        if opponent in self.observed_total and self.observed_total[opponent] > 0:
            defect_ratio = self.observed_defections.get(opponent, 0) / self.observed_total[opponent]
            penalty = defect_ratio * 0.5
            coop_rate -= penalty
        if opponent in self.opponent_streaks:
            streak = self.opponent_streaks[opponent]
            if streak < 0:
                coop_rate -= abs(streak) * 0.1
        # Trust adjustment based on overall cooperation rate in all observations
        if opponent in self.observed_total and self.observed_total[opponent] > 0:
            coop_ratio = self.observed_cooperations.get(opponent, 0) / self.observed_total[opponent]
            trust_bonus = (coop_ratio - 0.5) * 0.2
