            if opponent in self.recent_opp_variance and len(self.recent_opp_variance[opponent]) >= 3:
                recent_acts = self.recent_opp_variance[opponent]
                mean = sum(recent_acts) / len(recent_acts)
                variance = sum((x - mean) ** 2 for x in recent_acts) / len(recent_acts)
            if variance is not None and variance > 0.2:
