            total = len(self.history[key])
            opp_coop_rate = coop / total
            recent_defections = self.defection_memory.get(opponent, 0)
            # More aggressive retaliation: defect if 2 or more recent defections
            if recent_defections >= 2 and self.round - self.defection_memory.get(f'{opponent}_last', 0) <= 3:
