                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                return True
            else:
                # Reduced generosity: less likely to cooperate with bad opponents
                if len(self.history[key]) > 5 and random.random() < self.generosity:
                    return True
                return False
        else:
            # More cautious on first encounter
            return self.reputation[opponent] >= self.trust_threshold or random.random() < 0.05

