        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.coop_rate = {}
        self.my_actions = []
        self.round = 0
        self.trust_threshold = 0.35
        self.memory_limit = 30
        self.third_party_obs = {}
        self.last_opponent = None
        self.coop_streak = 0
        self.recent_opponents = []
        self.opponent_frequency = {}
        self.defection_memory = {}
        self.partner_recent_coop = {}
        self.generosity = 0.15
        self.empathy = 0.1
        self.opponent_action_history = {}
        self.opponent_run = {}
        self.opponent_run_length = {}
        self.opponent_run_type = {}
        self.long_term_coop = {}
        self.opponent_recent_coop = {}
        self.self_recent_coop = []
        # New: Track opponent's cooperation streak to reward sustained cooperation
        self.opponent_coop_streak = {}
        # New: Track opponent's defection streak to punish sustained defection
        self.opponent_defect_streak = {}
        # New: Track recent interactions with each opponent for adaptive trust
        self.opponent_interaction_count = {}
        # New: Track opponent's action in last interaction for pattern detection
        self.opponent_last_action = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5
        key = (self.agent_id, opponent)
        if key in self.history and len(self.history[key]) > 0:
            coop = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            opp_coop_rate = coop / total
            recent_defections = self.defection_memory.get(opponent, 0)
            if recent_defections >= 3 and self.round - self.defection_memory.get(f'{opponent}_last', 0) <= 2:
                return False
            recent_coop = self.partner_recent_coop.get(opponent, 0)
            recent_coop_rate = self.opponent_recent_coop.get(opponent, 0.5)
            my_recent_coop_rate = sum(self.self_recent_coop) / len(self.self_recent_coop) if self.self_recent_coop else 0.5
            # New: Check opponent's cooperation streak - if long, be generous
            coop_streak = self.opponent_coop_streak.get(opponent, 0)
            # New: Check opponent's defection streak - if long, be cautious
            defect_streak = self.opponent_defect_streak.get(opponent, 0)
            # New: Check interaction count to adjust trust threshold adaptively
            interaction_count = self.opponent_interaction_count.get(opponent, 0)
            adaptive_threshold = 0.35 - 0.01 * min(interaction_count, 10)  # Lower threshold with experience
            if opp_coop_rate >= 0.5 or self.reputation[opponent] >= adaptive_threshold:
                if recent_coop >= 2:
                    return True
                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                if my_recent_coop_rate > 0.8 and random.random() < 0.3:
                    return False
                # New: If opponent has a long cooperation streak, reward with cooperation
                if coop_streak >= 5:
                    return True
                # New: If opponent has a long defection streak despite good reputation, be cautious
                if defect_streak >= 3:
                    return random.random() < 0.3
                return True
            else:
                if recent_coop_rate >= 0.5 and random.random() < 0.2:
                    return True
                if len(self.history[key]) > 5 and random.random() < self.generosity:
                    return True
                if my_recent_coop_rate < 0.3 and random.random() < 0.15:
                    return True
                # New: If opponent has been cooperating recently, give a chance even if overall rate low
                if recent_coop_rate >= 0.4 and random.random() < 0.1:
                    return True
                # New: If opponent has a short defection streak (1-2), consider forgiving
                if defect_streak <= 2 and random.random() < 0.25:
                    return True
                return False
        else:
            # New: For first interaction, use reputation and a slight bias to cooperate
            return self.reputation[opponent] >= self.trust_threshold or random.random() < 0.15

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.my_actions.append(my_action)
            if len(self.my_actions) > self.memory_limit:
                self.my_actions.pop(0)
            self.self_recent_coop.append(1 if my_action == 'cooperate' else 0)
            if len(self.self_recent_coop) > 10:
                self.self_recent_coop.pop(0)
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            key = (self.agent_id, opponent)
            if key not in self.history:
                self.history[key] = []
            self.history[key].append((my_action, opp_action, self.round))
            if len(self.history[key]) > self.memory_limit:
                self.history[key].pop(0)
            coop_count = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            self.coop_rate[opponent] = coop_count / total if total > 0 else 0.5
            if opponent not in self.opponent_recent_coop:
                self.opponent_recent_coop[opponent] = []
            self.opponent_recent_coop[opponent].append(1 if opp_action == 'cooperate' else 0)
            if len(self.opponent_recent_coop[opponent]) > 5:
                self.opponent_recent_coop[opponent].pop(0)
            if len(self.opponent_recent_coop[opponent]) >= 5:
                self.opponent_recent_coop[opponent] = sum(self.opponent_recent_coop[opponent]) / len(self.opponent_recent_coop[opponent])
            else:
                self.opponent_recent_coop[opponent] = sum(self.opponent_recent_coop[opponent]) / len(self.opponent_recent_coop[opponent]) if self.opponent_recent_coop[opponent] else 0.5
            if opponent not in self.long_term_coop:
                self.long_term_coop[opponent] = [0, 0]
            if opp_action == 'cooperate':
                self.long_term_coop[opponent][0] += 1
            self.long_term_coop[opponent][1] += 1
            delta = 0.12 if opp_action == 'cooperate' else -0.08
            self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + delta))
            # New: Update cooperation/defection streaks
            if opp_action == 'cooperate':
                self.opponent_coop_streak[opponent] = self.opponent_coop_streak.get(opponent, 0) + 1
                self.opponent_defect_streak[opponent] = 0
            else:
                self.opponent_defect_streak[opponent] = self.opponent_defect_streak.get(opponent, 0) + 1
                self.opponent_coop_streak[opponent] = 0
            # New: Track interaction count
            self.opponent_interaction_count[opponent] = self.opponent_interaction_count.get(opponent, 0) + 1
            # New: Track last action
            self.opponent_last_action[opponent] = opp_action
            if self.last_opponent == opponent:
                if opp_action == 'cooperate':
                    self.coop_streak += 1
                else:
                    self.coop_streak = 0
            else:
                self.coop_streak = 1 if opp_action == 'cooperate' else 0
            self.last_opponent = opponent
            self.recent_opponents.append((opponent, self.round))
            if len(self.recent_opponents) > self.memory_limit:
                self.recent_opponents.pop(0)
            self.opponent_frequency[opponent] = self.opponent_frequency.get(opponent, 0) + 1
            if opp_action == 'defect':
                self.defection_memory[opponent] = self.defection_memory.get(opponent, 0) + 1
                self.defection_memory[f'{opponent}_last'] = self.round
            else:
                self.defection_memory[opponent] = 0
            if opp_action == 'cooperate':
                self.partner_recent_coop[opponent] = self.partner_recent_coop.get(opponent, 0) + 1
            else:
                self.partner_recent_coop[opponent] = 0
            if opponent not in self.opponent_action_history:
                self.opponent_action_history[opponent] = []
            self.opponent_action_history[opponent].append(opp_action)
            if len(self.opponent_action_history[opponent]) > 10:
                self.opponent_action_history[opponent].pop(0)
            if opponent not in self.opponent_run_type:
                self.opponent_run_type[opponent] = None
                self.opponent_run_length[opponent] = 0
            if self.opponent_run_type[opponent] == opp_action:
                self.opponent_run_length[opponent] += 1
            else:
                self.opponent_run_type[opponent] = opp_action
                self.opponent_run_length[opponent] = 1
            self.opponent_run[opponent] = (opp_action, self.opponent_run_length[opponent])
        else:
            if donor_action == 'cooperate':
                delta_d = 0.07 + self.empathy
            else:
                delta_d = -0.05
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation.get(donor_id, 0.5) + delta_d))
            if recipient_action == 'cooperate':
                delta_r = 0.05
            else:
                delta_r = -0.03
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation.get(recipient_id, 0.5) + delta_r))
            key_donor = donor_id
            if key_donor not in self.third_party_obs:
                self.third_party_obs[key_donor] = []
            self.third_party_obs[key_donor].append(donor_action)
            if len(self.third_party_obs[key_donor]) > self.memory_limit:
                self.third_party_obs[key_donor].pop(0)
            if len(self.third_party_obs[key_donor]) >= 5:
                coop_count = sum(1 for act in self.third_party_obs[key_donor] if act == 'cooperate')
                rate = coop_count / len(self.third_party_obs[key_donor])
                if rate >= 0.7:
                    self.reputation[key_donor] = max(0.0, min(1.0, self.reputation.get(key_donor, 0.5) + 0.03))
                elif rate <= 0.3:
                    self.reputation[key_donor] = max(0.0, self.reputation.get(key_donor, 0.5) - 0.01)
        if self.last_opponent is not None and self.coop_streak >= 3:
            self.reputation[self.last_opponent] = max(0.0, min(1.0, self.reputation.get(self.last_opponent, 0.5) + 0.02))
        current_round = self.round
        recent_ids = {opp for opp, r in self.recent_opponents if current_round - r <= 5}
        for opp in list(self.reputation.keys()):
            if opp != self.agent_id and opp not in recent_ids:
                self.reputation[opp] = max(0.0, self.reputation[opp] - 0.003)
        if self.opponent_frequency and self.coop_rate:
            for opp, freq in self.opponent_frequency.items():
                if freq >= 3 and opp in self.coop_rate and self.coop_rate[opp] >= 0.6:
                    self.reputation[opp] = max(0.0, min(1.0, self.reputation.get(opp, 0.5) + 0.02))
        if opponent in self.opponent_action_history and len(self.opponent_action_history[opponent]) >= 5:
