            coop_count = recent_actions.count('cooperate')
            if coop_count >= 4:
                self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + 0.05))
            elif coop_count <= 1:
                self.reputation[opponent] = max(0.0, self.reputation.get(opponent, 0.5) - 0.05)
        if opponent in self.opponent_run:
            action, length = self.opponent_run[opponent]
            if action == 'cooperate' and length >= 5:
                self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + 0.03))
            elif action == 'defect' and length >= 3:
                self.reputation[opponent] = max(0.0, self.reputation.get(opponent, 0.5) - 0.03)
        if opponent in self.long_term_coop and self.long_term_coop[opponent][1] >= 10:
            coop_ratio = self.long_term_coop[opponent][0] / self.long_term_coop[opponent][1]
            if coop_ratio >= 0.7:
                self.generosity = min(0.4, self.generosity + 0.02)
            elif coop_ratio <= 0.3:
                self.generosity = max(0.0, self.generosity - 0.02)
        if opponent in self.opponent_recent_coop:
            recent_rate = self.opponent_recent_coop[opponent]
            if recent_rate >= 0.8:
                self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + 0.02))
            elif recent_rate <= 0.2:
                self.reputation[opponent] = max(0.0, self.reputation.get(opponent, 0.5) - 0.02)

