            recent_defect_freq = self.opponent_recent_defections.get(opponent, 0.0)
            if recent_defect_freq > 0.5:
                adaptive_threshold += 0.1
            if opp_coop_rate >= 0.5 or self.reputation[opponent] >= adaptive_threshold:
                if recent_coop >= 2:
                    return True
                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                if my_recent_coop_rate > 0.8 and random.random() < 0.3:
                    return False
                if coop_streak >= 5:
                    return True
                if defect_streak >= 3:
                    return random.random() < 0.3
                if recent_defect_freq > 0.4 and random.random() < 0.2:
                    return False
                return True
            else:
                if recent_coop_rate >= 0.5 and random.random() < 0.2:
