    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5
        key = (self.agent_id, opponent)
        if key in self.history and len(self.history[key]) > 0:
            coop = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            opp_coop_rate = coop / total
            recent_defections = self.defection_memory.get(opponent, 0)
            if recent_defections >= 3 and self.round - self.defection_memory.get(f'{opponent}_last', 0) <= 2:
                return False
            recent_coop = self.partner_recent_coop.get(opponent, 0)
            recent_coop_rate = self.opponent_recent_coop.get(opponent, 0.5)
            my_recent_coop_rate = sum(self.self_recent_coop) / len(self.self_recent_coop) if self.self_recent_coop else 0.5
            recent_def_count = self.recent_defection_count.get(opponent, 0)
