            if volatility > self.volatility_threshold:
                self.adaptive_threshold += 0.03
            # Mutation: Added a forgiveness mechanism that can override defection detection
            if recent_def_count >= 2 and self.forgiveness_counter.get(opponent, 0) >= 2:
