                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                if my_recent_coop_rate > 0.8 and random.random() < 0.3:
                    return False
                if consistency < self.consistency_threshold and random.random() < 0.05:
                    return False
                return True
            else:
                if recent_coop_rate >= 0.5 and random.random() < 0.2:
                    return True
                if len(self.history[key]) > 5 and random.random() < self.generosity:
