            total = len(self.history[key])
            opp_coop_rate = coop / total
            recent_defections = self.defection_memory.get(opponent, 0)
            if recent_defections >= 3 and self.round - self.defection_memory.get(f'{opponent}_last', 0) <= 2:
                return False
            recent_coop = self.partner_recent_coop.get(opponent, 0)
            recent_coop_rate = self.opponent_recent_coop.get(opponent, 0.5)
            my_recent_coop_rate = sum(self.self_recent_coop) / len(self.self_recent_coop) if self.self_recent_coop else 0.5
            recent_def_count = self.recent_defection_count.get(opponent, 0)
            if recent_def_count >= 2 and self.forgiveness_counter.get(opponent, 0) < 2:
                return False
            consistency = self.opponent_consistency.get(opponent, 0.5)
            if self.defection_streak.get(opponent, 0) >= 2:
                self.adaptive_threshold = max(0.2, self.adaptive_threshold - 0.02)
            else:
                self.adaptive_threshold = min(0.45, self.adaptive_threshold + 0.01)
            volatility = self.reputation_volatility.get(opponent, 0.0)
            if volatility > self.volatility_threshold:
                self.adaptive_threshold += 0.03
            # Mutation: Added a forgiveness mechanism that can override defection detection
            if recent_def_count >= 2 and self.forgiveness_counter.get(opponent, 0) >= 2:
                if random.random() < 0.2:
                    return True
            if opp_coop_rate >= 0.5 or self.reputation[opponent] >= self.adaptive_threshold:
                if recent_coop >= 2:
                    return True
                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                if my_recent_coop_rate > 0.8 and random.random() < 0.3:
                    return False
                if consistency < self.consistency_threshold and random.random() < 0.05:
                    return False
                return True
            else:
                if recent_coop_rate >= 0.5 and random.random() < 0.2:
                    return True
                if len(self.history[key]) > 5 and random.random() < self.generosity:
                    return True
                if my_recent_coop_rate < 0.3 and random.random() < 0.15:
                    return True
                if self.forgiveness_counter.get(opponent, 0) > 0 and random.random() < 0.3:
                    return True
                if consistency > 0.8 and random.random() < 0.15:
