        self.round = 0
        self.trust_threshold = 0.35
        self.memory_limit = 30
        self.third_party_obs = {}
        self.last_opponent = None
        self.coop_streak = 0
        self.recent_opponents = []
        self.opponent_frequency = {}
        self.defection_memory = {}
        self.partner_recent_coop = {}
        self.generosity = 0.15
        self.empathy = 0.1
        self.opponent_action_history = {}
        self.opponent_run = {}
        self.opponent_run_length = {}
        self.opponent_run_type = {}
        self.long_term_coop = {}
        self.opponent_recent_coop = {}
        self.self_recent_coop = []
