                self.opponent_recent_coop[opponent].pop(0)
            if len(self.opponent_recent_coop[opponent]) >= 5:
                self.opponent_recent_coop[opponent] = sum(self.opponent_recent_coop[opponent]) / len(self.opponent_recent_coop[opponent])
            else:
                self.opponent_recent_coop[opponent] = sum(self.opponent_recent_coop[opponent]) / len(self.opponent_recent_coop[opponent]) if self.opponent_recent_coop[opponent] else 0.5
            if opponent not in self.long_term_coop:
                self.long_term_coop[opponent] = [0, 0]
            if opp_action == 'cooperate':
                self.long_term_coop[opponent][0] += 1
            self.long_term_coop[opponent][1] += 1
            delta = 0.12 if opp_action == 'cooperate' else -0.08
            self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + delta))
            if opponent not in self.recent_reputation:
                self.recent_reputation[opponent] = []
            self.recent_reputation[opponent].append(self.reputation[opponent])
            if len(self.recent_reputation[opponent]) > 10:
                self.recent_reputation[opponent].pop(0)
            if len(self.recent_reputation[opponent]) >= 3:
                recent_vals = self.recent_reputation[opponent]
                trend = recent_vals[-1] - recent_vals[0]
                self.reputation_trend[opponent] = trend
                self.dynamic_threshold_offset = min(0.1, max(-0.1, sum(self.reputation_trend.values()) * 0.01))
            if opponent not in self.opponent_long_term_avg:
                self.opponent_long_term_avg[opponent] = 0.5
            self.opponent_long_term_avg[opponent] = 0.9 * self.opponent_long_term_avg[opponent] + 0.1 * (1 if opp_action == 'cooperate' else 0)
