        if key in self.history and len(self.history[key]) > 0:
            coop = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            opp_coop_rate = coop / total
            recent_defections = self.defection_memory.get(opponent, 0)
            if recent_defections >= 3 and self.round - self.defection_memory.get(f'{opponent}_last', 0) <= 2:
                return False
            recent_coop = self.partner_recent_coop.get(opponent, 0)
            recent_coop_rate = self.opponent_recent_coop.get(opponent, 0.5)
            my_recent_coop_rate = sum(self.self_recent_coop) / len(self.self_recent_coop) if self.self_recent_coop else 0.5
            recent_def_count = self.recent_defection_count.get(opponent, 0)
            if recent_def_count >= 2 and self.forgiveness_counter.get(opponent, 0) < 2:
                return False
            consistency = self.opponent_consistency.get(opponent, 0.5)
            long_avg = self.opponent_long_term_avg.get(opponent, 0.5)
            if self.self_coop_streak >= 4 and random.random() < 0.1:
                return True
            trend = self.reputation_trend.get(opponent, 0)
            adjusted_threshold = self.trust_threshold + self.dynamic_threshold_offset - trend * 0.05
            if opp_coop_rate >= 0.5 or self.reputation[opponent] >= adjusted_threshold:
                if recent_coop >= 2:
                    return True
                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                if my_recent_coop_rate > 0.8 and random.random() < 0.3:
                    return False
                if consistency < self.consistency_threshold and random.random() < 0.05:
                    return False
                if long_avg < 0.4 and random.random() < 0.1:
                    return False
                return True
            else:
                if recent_coop_rate >= 0.5 and random.random() < 0.2:
                    return True
                if len(self.history[key]) > 5 and random.random() < self.generosity:
                    return True
                if my_recent_coop_rate < 0.3 and random.random() < 0.15:
                    return True
                if self.forgiveness_counter.get(opponent, 0) > 0 and random.random() < 0.3:
                    return True
                if consistency > 0.8 and random.random() < 0.15:
                    return True
                if long_avg > 0.6 and random.random() < 0.2:
                    return True
                if len(self.overall_recent_defections) >= 3 and random.random() < 0.1:
                    return False
                return False
        else:
            # New: Use a dynamic threshold and also consider own recent defection streak
            if self.defect_streak >= 3:
                return True
            return self.reputation[opponent] >= (self.trust_threshold + self.dynamic_threshold_offset) or random.random() < 0.1

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
