    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.coop_rate = {}
        self.my_actions = []
        self.round = 0
        self.trust_threshold = 0.35
        self.memory_limit = 30
        self.third_party_obs = {}
        self.last_opponent = None
        self.coop_streak = 0
        self.recent_opponents = []
        self.opponent_frequency = {}
        self.defection_memory = {}
        self.partner_recent_coop = {}
        self.generosity = 0.15
        self.empathy = 0.1
        self.opponent_action_history = {}
        self.opponent_run = {}
        self.opponent_run_length = {}
        self.opponent_run_type = {}
        self.long_term_coop = {}
        self.opponent_recent_coop = {}
        self.self_recent_coop = []
        self.recent_defection_count = {}
        self.forgiveness_counter = {}
        self.opponent_consistency = {}
        self.consistency_threshold = 0.6
        self.defection_streak = {}
        self.adaptive_threshold = 0.35
        self.reputation_volatility = {}
        self.volatility_threshold = 0.2
        self.opponent_action_history_str = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5
        key = (self.agent_id, opponent)
        if key in self.history and len(self.history[key]) > 0:
            coop = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            opp_coop_rate = coop / total
            recent_defections = self.defection_memory.get(opponent, 0)
            if recent_defections >= 3 and self.round - self.defection_memory.get(f'{opponent}_last', 0) <= 2:
                return False
            recent_coop = self.partner_recent_coop.get(opponent, 0)
            recent_coop_rate = self.opponent_recent_coop.get(opponent, 0.5)
            my_recent_coop_rate = sum(self.self_recent_coop) / len(self.self_recent_coop) if self.self_recent_coop else 0.5
            recent_def_count = self.recent_defection_count.get(opponent, 0)
            if recent_def_count >= 2 and self.forgiveness_counter.get(opponent, 0) < 2:
                return False
            consistency = self.opponent_consistency.get(opponent, 0.5)
            if self.defection_streak.get(opponent, 0) >= 2:
                self.adaptive_threshold = max(0.2, self.adaptive_threshold - 0.02)
            else:
                self.adaptive_threshold = min(0.45, self.adaptive_threshold + 0.01)
            volatility = self.reputation_volatility.get(opponent, 0.0)
            if volatility > self.volatility_threshold:
                self.adaptive_threshold += 0.03
            if recent_def_count >= 2 and self.forgiveness_counter.get(opponent, 0) >= 2:
                if random.random() < 0.2:
                    return True
            if opp_coop_rate >= 0.5 or self.reputation[opponent] >= self.adaptive_threshold:
                if recent_coop >= 2:
                    return True
                if opp_coop_rate >= 0.45 and random.random() < 0.1:
                    return True
                if my_recent_coop_rate > 0.8 and random.random() < 0.3:
                    return False
                if consistency < self.consistency_threshold and random.random() < 0.05:
                    return False
                return True
            else:
                if recent_coop_rate >= 0.5 and random.random() < 0.2:
                    return True
                if len(self.history[key]) > 5 and random.random() < self.generosity:
                    return True
                if my_recent_coop_rate < 0.3 and random.random() < 0.15:
                    return True
                if self.forgiveness_counter.get(opponent, 0) > 0 and random.random() < 0.3:
                    return True
                if consistency > 0.8 and random.random() < 0.15:
                    return True
                return False
        else:
            # Mutation: Slightly more cautious with unknown opponents but still open to cooperation
            return self.reputation[opponent] >= self.adaptive_threshold or random.random() < 0.08

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.my_actions.append(my_action)
            if len(self.my_actions) > self.memory_limit:
                self.my_actions.pop(0)
            self.self_recent_coop.append(1 if my_action == 'cooperate' else 0)
            if len(self.self_recent_coop) > 10:
                self.self_recent_coop.pop(0)
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            key = (self.agent_id, opponent)
            if key not in self.history:
                self.history[key] = []
            self.history[key].append((my_action, opp_action, self.round))
            if len(self.history[key]) > self.memory_limit:
                self.history[key].pop(0)
            coop_count = sum(1 for _, act, _ in self.history[key] if act == 'cooperate')
            total = len(self.history[key])
            self.coop_rate[opponent] = coop_count / total if total > 0 else 0.5
            if opponent not in self.opponent_recent_coop:
                self.opponent_recent_coop[opponent] = []
            self.opponent_recent_coop[opponent].append(1 if opp_action == 'cooperate' else 0)
            if len(self.opponent_recent_coop[opponent]) > 5:
                self.opponent_recent_coop[opponent].pop(0)
            if len(self.opponent_recent_coop[opponent]) >= 5:
                self.opponent_recent_coop[opponent] = sum(self.opponent_recent_coop[opponent]) / len(self.opponent_recent_coop[opponent])
            else:
                self.opponent_recent_coop[opponent] = sum(self.opponent_recent_coop[opponent]) / len(self.opponent_recent_coop[opponent]) if self.opponent_recent_coop[opponent] else 0.5
            if opponent not in self.long_term_coop:
                self.long_term_coop[opponent] = [0, 0]
            if opp_action == 'cooperate':
                self.long_term_coop[opponent][0] += 1
            self.long_term_coop[opponent][1] += 1
            delta = 0.12 if opp_action == 'cooperate' else -0.08
            old_rep = self.reputation.get(opponent, 0.5)
            self.reputation[opponent] = max(0.0, min(1.0, old_rep + delta))
            change = abs(self.reputation[opponent] - old_rep)
            if opponent not in self.reputation_volatility:
                self.reputation_volatility[opponent] = 0.0
            self.reputation_volatility[opponent] = 0.7 * self.reputation_volatility[opponent] + 0.3 * change
            if opponent not in self.opponent_consistency:
                self.opponent_consistency[opponent] = 0.5
            if opponent not in self.opponent_action_history:
                self.opponent_action_history[opponent] = []
            self.opponent_action_history[opponent].append(1 if opp_action == 'cooperate' else 0)
            if len(self.opponent_action_history[opponent]) > 10:
                self.opponent_action_history[opponent].pop(0)
            if len(self.opponent_action_history[opponent]) >= 5:
                actions = self.opponent_action_history[opponent]
                majority = max(set(actions), key=actions.count)
                consistency = actions.count(majority) / len(actions)
                self.opponent_consistency[opponent] = consistency
            if self.last_opponent == opponent:
                if opp_action == 'cooperate':
                    self.coop_streak += 1
                else:
                    self.coop_streak = 0
            else:
                self.coop_streak = 1 if opp_action == 'cooperate' else 0
            self.last_opponent = opponent
            self.recent_opponents.append((opponent, self.round))
            if len(self.recent_opponents) > self.memory_limit:
                self.recent_opponents.pop(0)
            self.opponent_frequency[opponent] = self.opponent_frequency.get(opponent, 0) + 1
            # Mutation: Add a cooperation streak bonus (but also a defect streak penalty)
            if opp_action == 'cooperate':
                self.coop_streak += 1
                if self.coop_streak >= 3:
                    self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + 0.05))
            else:
                self.coop_streak = 0
                # Mutation: Defect streaks are punished more harshly
                if self.defection_streak.get(opponent, 0) >= 3:
                    self.reputation[opponent] = max(0.0, self.reputation.get(opponent, 0.5) - 0.08)
            if opp_action == 'defect':
                self.defection_memory[opponent] = self.defection_memory.get(opponent, 0) + 1
                self.defection_memory[f'{opponent}_last'] = self.round
                if opponent not in self.recent_defection_count:
                    self.recent_defection_count[opponent] = 0
                self.recent_defection_count[opponent] += 1
                if self.recent_defection_count[opponent] >= 2:
                    self.forgiveness_counter[opponent] = self.forgiveness_counter.get(opponent, 0) + 1
                self.defection_streak[opponent] = self.defection_streak.get(opponent, 0) + 1
            else:
                self.defection_memory[opponent] = 0
                if self.forgiveness_counter.get(opponent, 0) > 0:
                    self.forgiveness_counter[opponent] = 0
                self.defection_streak[opponent] = 0
            if opp_action == 'cooperate':
                self.partner_recent_coop[opponent] = self.partner_recent_coop.get(opponent, 0) + 1
            else:
                self.partner_recent_coop[opponent] = 0
            if opponent not in self.opponent_action_history_str:
                self.opponent_action_history_str[opponent] = []
            self.opponent_action_history_str[opponent].append(opp_action)
            if len(self.opponent_action_history_str[opponent]) > 10:
                self.opponent_action_history_str[opponent].pop(0)
            if opponent not in self.opponent_run_type:
                self.opponent_run_type[opponent] = None
                self.opponent_run_length[opponent] = 0
            if self.opponent_run_type[opponent] == opp_action:
                self.opponent_run_length[opponent] += 1
            else:
                self.opponent_run_type[opponent] = opp_action
                self.opponent_run_length[opponent] = 1
            self.opponent_run[opponent] = (opp_action, self.opponent_run_length[opponent])
        else:
            if donor_action == 'cooperate':
                delta_d = 0.07 + self.empathy
            else:
                delta_d = -0.05
            old_donor_rep = self.reputation.get(donor_id, 0.5)
            self.reputation[donor_id] = max(0.0, min(1.0, old_donor_rep + delta_d))
            change = abs(self.reputation[donor_id] - old_donor_rep)
            if donor_id not in self.reputation_volatility:
                self.reputation_volatility[donor_id] = 0.0
            self.reputation_volatility[donor_id] = 0.7 * self.reputation_volatility[donor_id] + 0.3 * change
            if recipient_action == 'cooperate':
                delta_r = 0.05
            else:
                delta_r = -0.03
            old_recipient_rep = self.reputation.get(recipient_id, 0.5)
            self.reputation[recipient_id] = max(0.0, min(1.0, old_recipient_rep + delta_r))
            change = abs(self.reputation[recipient_id] - old_recipient_rep)
            if recipient_id not in self.reputation_volatility:
                self.reputation_volatility[recipient_id] = 0.0
            self.reputation_volatility[recipient_id] = 0.7 * self.reputation_volatility[recipient_id] + 0.3 * change
            key_donor = donor_id
            if key_donor not in self.third_party_obs:
                self.third_party_obs[key_donor] = []
            self.third_party_obs[key_donor].append(donor_action)
            if len(self.third_party_obs[key_donor]) > self.memory_limit:
                self.third_party_obs[key_donor].pop(0)
            if len(self.third_party_obs[key_donor]) >= 5:
                coop_count = sum(1 for act in self.third_party_obs[key_donor] if act == 'cooperate')
                rate = coop_count / len(self.third_party_obs[key_donor])
                if rate >= 0.7:
                    self.reputation[key_donor] = max(0.0, min(1.0, self.reputation.get(key_donor, 0.5) + 0.03))
                elif rate <= 0.3:
                    self.reputation[key_donor] = max(0.0, self.reputation.get(key_donor, 0.5) - 0.01)
        # Mutation: More aggressive reputation decay for agents not seen recently
        current_round = self.round
        recent_ids = {opp for opp, r in self.recent_opponents if current_round - r <= 5}
        for opp in list(self.reputation.keys()):
            if opp != self.agent_id and opp not in recent_ids:
                self.reputation[opp] = max(0.0, self.reputation[opp] - 0.01)  # Increased decay
        if self.opponent_frequency and self.coop_rate:
            for opp, freq in self.opponent_frequency.items():
                if freq >= 3 and opp in self.coop_rate and self.coop_rate[opp] >= 0.6:
                    self.reputation[opp] = max(0.0, min(1.0, self.reputation.get(opp, 0.5) + 0.02))
        if opponent in self.opponent_action_history_str and len(self.opponent_action_history_str[opponent]) >= 5:
            recent_actions = self.opponent_action_history_str[opponent][-5:]
            coop_count = recent_actions.count('cooperate')
            if coop_count >= 4:
                self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + 0.05))
            elif coop_count <= 1:
                self.reputation[opponent] = max(0.0, self.reputation.get(opponent, 0.5) - 0.05)
        if opponent in self.opponent_run:
            action, length = self.opponent_run[opponent]
            if action == 'cooperate' and length >= 5:
                self.reputation[opponent] = max(0.0, min(1.0, self.reputation.get(opponent, 0.5) + 0.03))
            elif action == 'defect' and length >= 3:
                self.reputation[opponent] = max(0.0, self.reputation.get(opponent, 0.5) - 0.05)

import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.coop_rate = {}
        self.my_actions = []
        self.round = 0
        self.trust_threshold = 0.35
        self.memory_limit = 30
        self.third_party_obs = {}
        self.last_opponent = None
        self.coop_streak = 0
        self.recent_opponents = []
        self.opponent_frequency = {}
