                self.overall_recent_defections.append(self.round)
                if len(self.overall_recent_defections) > 10:
                    self.overall_recent_defections.pop(0)
            else:
                self.defection_memory[opponent] = 0
                if self.forgiveness_counter.get(opponent, 0) > 0:
                    self.forgiveness_counter[opponent] = 0
